#!/usr/bin/env bash
# Generated by Capsules (template 1.2.0).
# Writes a plain ~/.zshrc, installs the pinned agent CLIs (versions in
# agent-versions.sh) and records the installed versions. The Dev Container
# CLI runs it once per new container.
# ensure-agents.sh runs it again only when an earlier install did not finish or
# the pinned versions changed, so tools are never upgraded silently.
set -euo pipefail

script_dir="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
# shellcheck source=agent-versions.sh
. "$script_dir/agent-versions.sh"
versions_file="$script_dir/installed-versions.txt"

bash "$script_dir/link-tool-state.sh"

# Plain zsh: a small ~/.zshrc, so zsh starts without its new-user wizard and
# without the Oh My Zsh setup the base image ships. An existing ~/.zshrc is
# kept unless it is that Oh My Zsh one, so your own edits survive a re-run.
zshrc="$HOME/.zshrc"
if [ ! -f "$zshrc" ] || grep -q 'oh-my-zsh\.sh' "$zshrc"; then
  cat > "$zshrc.tmp" <<'ZSHRC'
# Created by Capsules: plain zsh, no framework. Edit freely; Capsules keeps
# this file once it exists.
HISTFILE="$HOME/.zsh_history"
HISTSIZE=10000
SAVEHIST=10000
setopt append_history hist_ignore_dups
bindkey -e
autoload -Uz compinit && compinit -u
PROMPT='%F{green}%n%f %F{blue}%~%f %# '
ZSHRC
  mv -f "$zshrc.tmp" "$zshrc"
fi

npm install -g \
  "@anthropic-ai/claude-code@${CLAUDE_CODE_VERSION}" \
  "@openai/codex@${CODEX_VERSION}" \
  "@github/copilot@${COPILOT_VERSION}"

# Fail the build visibly when a tool is not on PATH.
claude_version="$(claude --version)"
codex_version="$(codex --version)"
copilot_version="$(copilot --version)"
copilot_version="${copilot_version%%$'\n'*}"

# Written to a temporary file and renamed, so a partial file never looks complete.
{
  echo "# Recorded by post-create.sh; ignored by Git."
  echo "template: 1.2.0"
  echo "recorded_at: $(date -u +%Y-%m-%dT%H:%M:%SZ)"
  echo "os: $( (. /etc/os-release && echo "${PRETTY_NAME:-unknown}") 2>/dev/null || echo unknown)"
  echo "node: $(node --version)"
  echo "npm: $(npm --version)"
  echo "git: $(git --version)"
  echo "zsh: $( (zsh --version) 2>/dev/null || echo "not installed")"
  echo "@anthropic-ai/claude-code: ${CLAUDE_CODE_VERSION} (${claude_version})"
  echo "@openai/codex: ${CODEX_VERSION} (${codex_version})"
  echo "@github/copilot: ${COPILOT_VERSION} (${copilot_version})"
} > "$versions_file.tmp"
mv -f "$versions_file.tmp" "$versions_file"

# Project dependencies go into the container-only node_modules volume
# (devcontainer.json mounts), never into the host's node_modules.
if [ -f "$script_dir/../package-lock.json" ]; then
  (cd "$script_dir/.." && npm ci --no-fund --no-audit)
fi

# Last step: the marker says the install finished. ensure-agents.sh reads it.
expected_agents_marker > "$AGENTS_MARKER.tmp"
mv -f "$AGENTS_MARKER.tmp" "$AGENTS_MARKER"

echo
cat "$versions_file"
